#import <Foundation/Foundation.h>
#import "OtamatoneCore.h"
#include <math.h>
static OtamaSettings gSettings;
void SettingInitialize(void){NSUserDefaults*d=[NSUserDefaults standardUserDefaults];[d registerDefaults:@{@"volume":@.82,@"octave":@1,@"follow":@YES,@"hideFukidashi":@NO,@"skin":@0,@"recordHold":@NO}];gSettings.volume=[d floatForKey:@"volume"];gSettings.octave=(int)[d integerForKey:@"octave"];gSettings.followMode=[d boolForKey:@"follow"];gSettings.hideFukidashi=[d boolForKey:@"hideFukidashi"];gSettings.skin=(int)[d integerForKey:@"skin"];gSettings.recordHoldMode=[d boolForKey:@"recordHold"];}
void SettingSave(void){NSUserDefaults*d=[NSUserDefaults standardUserDefaults];[d setFloat:gSettings.volume forKey:@"volume"];[d setInteger:gSettings.octave forKey:@"octave"];[d setBool:gSettings.followMode forKey:@"follow"];[d setBool:gSettings.hideFukidashi forKey:@"hideFukidashi"];[d setInteger:gSettings.skin forKey:@"skin"];[d setBool:gSettings.recordHoldMode forKey:@"recordHold"];}
const OtamaSettings *SettingState(void){return &gSettings;}void SettingSetVolume(float v){gSettings.volume=fmaxf(0,fminf(1,v));SettingSave();}void SettingSetOctave(int v){gSettings.octave=MAX(0,MIN(2,v));SettingSave();}void SettingSetFollow(bool v){gSettings.followMode=v;SettingSave();}void SettingSetHideFukidashi(bool v){gSettings.hideFukidashi=v;SettingSave();}void SettingSetSkin(int v){gSettings.skin=MAX(0,MIN(4,v));SettingSave();}void SettingSetRecordHoldMode(bool v){gSettings.recordHoldMode=v;SettingSave();}float SettingGetVolume(void){return gSettings.volume;}int SettingGetOctave(void){return gSettings.octave;}bool SettingIsFollow(void){return gSettings.followMode;}int SettingGetSkin(void){return gSettings.skin;}
